-- ============================================================================
-- NUTRICIÓN POR PRODUCTO
-- ----------------------------------------------------------------------------
-- nutricion: por 100 g de alimento crudo (por 100 g tal como se compra en lo
--            que trae hueso o espina): kcal, proteina, carbohidratos, grasa,
--            fibra y azucar, en gramos salvo las kcal.
-- gramos:    cuánto pesa cada medida de las recetas ({"diente": 4, "taza": 185}).
--            lb, g y kg se convierten solos.
-- Valores aproximados de la Tabla de Composición de Alimentos Colombianos
-- (ICBF) y de USDA FoodData Central. Sirven para orientarse, no son exactos.
-- ============================================================================

alter table public.productos
  add column nutricion jsonb,
  add column gramos jsonb not null default '{}'::jsonb;

update public.productos p
set nutricion = v.nutricion, gramos = v.gramos
